export interface WebSocketMessage {
    id: string;
    command: string;
    params: Record<string, unknown>;
}
export interface WebSocketResponse {
    id: string;
    success: boolean;
    result?: unknown;
    error?: string;
}
export interface PendingRequest {
    resolve: (value: unknown) => void;
    reject: (reason: Error) => void;
    timeout: NodeJS.Timeout;
}
export interface FigmaNode {
    id: string;
    name: string;
    type: string;
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    children?: FigmaNode[];
}
export interface CreateFrameParams {
    name: string;
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    parentId?: string;
}
export interface CreateRectangleParams {
    name?: string;
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    fillColor?: {
        r: number;
        g: number;
        b: number;
        a?: number;
    };
    parentId?: string;
}
export interface CreateTextParams {
    text: string;
    name?: string;
    x?: number;
    y?: number;
    fontSize?: number;
    fontFamily?: string;
    fillColor?: {
        r: number;
        g: number;
        b: number;
        a?: number;
    };
    parentId?: string;
}
export interface CreateInstanceParams {
    componentKey: string;
    x?: number;
    y?: number;
    parentId?: string;
}
export interface UpdateNodeParams {
    nodeId: string;
    properties: {
        name?: string;
        x?: number;
        y?: number;
        width?: number;
        height?: number;
        fillColor?: {
            r: number;
            g: number;
            b: number;
            a?: number;
        };
        opacity?: number;
        visible?: boolean;
        locked?: boolean;
        text?: string;
        fontSize?: number;
    };
}
export interface DeleteNodeParams {
    nodeId: string;
}
export interface GetNodeParams {
    nodeId: string;
}
export interface CaptureScreenshotParams {
    nodeId: string;
    scale?: number;
    format?: 'PNG' | 'JPG' | 'SVG' | 'PDF';
}
